import{z as A,x as d,o as r,c as p,q as E,j as s,D as e,d as t,s as n,S as o,b as i}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"差分隐私","description":"","frontmatter":{"title":"差分隐私","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/differential-privacy.md","filePath":"cs/differential-privacy.md","lastUpdated":1791413859000}'),D={name:"cs/differential-privacy.md"};function B(h,a,m,c,f,u){const l=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=E('<h1 id="差分隐私" tabindex="-1">差分隐私 <a class="header-anchor" href="#差分隐私" aria-label="Permalink to &quot;差分隐私&quot;">​</a></h1><div class="epigraph"><p>差分隐私给发布机制一张证明：任意一条记录在或不在，对输出分布的影响有界。隐私损失可加，预算要记账。它不靠「匿名化感觉」。</p><footer>—— Dwork, McSherry, Nissim and Smith, Calibrating Noise to Sensitivity, TCC 2006；Dwork and Roth, *The Algorithmic Foundations of Differential Privacy*</footer></div><p>上一课<a href="/cs/container-escape">容器逃逸</a>结束系统硬件线；隐私单元从可证明的发布机制起步。缺口是<strong>聚合查询的输出仍可能认出个体</strong>——两次计数相减就是一个人的答案。本课钉 ε-差分隐私，不重写密码学。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚合也挡不住差分攻击：知道某人已在总表，再查含她的子集计数，相减即知她的属性。DP 的合同：相邻数据集（只差一条记录）上，机制输出分布的似然比不超过 \\(e^\\varepsilon\\)——任意一条记录在或不在，任何结论的概率都几乎不变。缺口是三件：灵敏度怎么算、噪声怎么按灵敏度校准、多次查询怎么记账。</p><p><span class="marginnote">数字实例：\\(\\varepsilon=0.1\\) 意味着无论张三在不在数据集里，你看到任何输出的概率比至多 \\(e^{0.1}\\approx1.105\\)——只差一成左右；而 \\(\\varepsilon=10\\) 时 \\(e^{10}\\) 上万倍，这条「几乎不变」基本不设防。所以 ε 取值大小就是隐私强弱本身。</span></p><p><span class="marginnote">常见误区：以为「匿名化 = 删掉姓名」就安全了。Netflix 大赛与纽约出租车数据都证明：把两份「匿名」表相减、或拿外部数据一对齐，个体照样现形。差分隐私防的正是这类「任意背景知识」的攻击，而不是赌对手手里的信息不够多。</span></p><h3 id="不是加密" tabindex="-1">不是加密 <a class="header-anchor" href="#不是加密" aria-label="Permalink to &quot;不是加密&quot;">​</a></h3><p>不是加密：DP 保护的是发布结果的分布，服务器内部照常明文计算；要连计算过程也不暴露，得另叠 MPC 或同态——正交的层。</p><p><span class="marginnote">直觉类比：灵敏度 \\(\\Delta\\) 就是「一个人的答案最多能把结果撬动多少」。数人头时 \\(\\Delta=1\\)，一个人顶多让计数加一；查总收入时 \\(\\Delta\\) 等于最富那位的收入。噪声按 \\(\\Delta\\) 校准——先量出「一个人能掀多大浪」，再决定盖多厚的布。</span></p><p><span class="marginnote">DMNS 2006。k-匿名下一课是句法匿名，已被证明不够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是拉普拉斯机制：真值加按灵敏度 \\(\\Delta\\) 缩放的拉普拉斯噪声，\\(\\varepsilon\\) 越小噪声越大——DMNS 的贡献正是「按灵敏度校准」，噪声不多不少。会计用基本组合：\\(k\\) 次查询合计预算 \\(\\sum\\varepsilon_i\\)，预算花完不再回答；「预算可加」是这个体系区别于一切句法方法的地方。下一课 k-匿名对照。</p>',14)),(r(),s(o,null,{default:e(()=>[n(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20SENS%5B%22%E7%81%B5%E6%95%8F%E5%BA%A6%22%5D%0A%20%20SENS%20--%3E%20NOISE%5B%22%E6%A0%A1%E5%87%86%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NOISE%20--%3E%20OUT%5B%22%CE%B5%20%E5%8F%AF%E8%AF%81%E7%9A%84%E5%8F%91%E5%B8%83%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[t("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"机制的本质是把隐私变成可记账的量：每次发布从预算里扣 ε，组合定理保证总泄漏不超账面——「多问几次凑出个体」这条路被数学封死，且保证对任意攻击者与任意背景知识一致成立。代价在实用性：长尾小分组上的噪声过于显著，预算经不起高频消费。k-匿名下一课无这种预算语言。",-1)),a[5]||(a[5]=i("p",null,"上面那张图画「单次查询怎么加噪发布」；这张看预算账本：ε 怎么一次一次扣，扣完之后发生什么。",-1)),(r(),s(o,null,{default:e(()=>[n(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LEDGER%5B%22%E9%A2%84%E7%AE%97%E8%B4%A6%E6%9C%AC%20%CE%B5%20%E5%90%88%E8%AE%A1%201.0%22%5D%20--%3E%20Q1%5B%22%E6%9F%A5%E8%AF%A21%20%E6%89%A3%200.5%20%E5%89%A9%200.5%22%5D%0A%20%20Q1%20--%3E%20Q2%5B%22%E6%9F%A5%E8%AF%A22%20%E6%89%A3%200.3%20%E5%89%A9%200.2%22%5D%0A%20%20Q2%20--%3E%20Q3%5B%22%E6%9F%A5%E8%AF%A23%20%E6%83%B3%E6%89%A3%200.4%22%5D%0A%20%20Q3%20--%3E%20DENY%7B%22%E4%BD%99%E9%A2%9D%E5%A4%9F%E5%90%97%22%7D%0A%20%20DENY%20--%20%22%E4%B8%8D%E5%A4%9F%22%20--%3E%20STOP%5B%22%E6%8B%92%E7%BB%9D%E5%9B%9E%E7%AD%94%20%E5%A0%B5%E6%AD%BB%E5%A4%9A%E6%AC%A1%E7%9B%B8%E5%87%8F%E5%87%91%E4%B8%AA%E4%BD%93%22%5D%0A%20%20DENY%20--%20%22%E5%A4%9F%20%E4%B8%94%E6%81%B0%E5%A5%BD%E6%89%A3%200.2%22%20--%3E%20EMPTY%5B%22%E9%A2%84%E7%AE%97%E8%8A%B1%E5%AE%8C%20%E6%9C%AC%E6%9C%9F%E6%B2%89%E9%BB%98%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把 ε 选成口号：ε=10 与 ε=0.1 是天壤，各部署的常见值差异很大，声明必须连带机制与预算账。k-匿名下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>隔离课之后，发布数据要另套合同。</li><li>DP：相邻集输出近，预算可加。</li><li>不是加密，也不是感觉匿名。</li><li>下一课 k-匿名。</li><li>出处：Dwork, McSherry, Nissim and Smith, 2006；Dwork and Roth。</li></ul>',4))])}const k=A(D,[["render",B]]);export{S as __pageData,k as default};
